'use client'

import { cn } from '@/lib/utils'
import {
  useOAuthConsent,
  type OAuthConsentDecision,
} from '@/registry/default/blocks/oauth-consent/hooks/use-oauth-consent'
import { Button } from '@/registry/default/components/ui/button'
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from '@/registry/default/components/ui/card'

const getInitial = (value: string) => value.trim().charAt(0).toUpperCase() || '?'

interface ConsentCardShellProps extends React.ComponentPropsWithoutRef<'div'> {
  clientName: string
  productName: string
}

function ConsentCardShell({
  clientName,
  productName,
  className,
  children,
  ...props
}: ConsentCardShellProps) {
  return (
    <div className={cn('flex flex-col gap-6', className)} {...props}>
      <Card>
        <CardHeader className="items-center space-y-4 text-center">
          <div
            className="flex items-center justify-center"
            aria-label={`${clientName} connecting to ${productName}`}
          >
            <div className="flex size-12 items-center justify-center rounded-full border bg-muted font-medium">
              {getInitial(clientName)}
            </div>
            <div className="h-px w-8 bg-border" aria-hidden="true" />
            <div className="flex size-12 items-center justify-center rounded-full border bg-muted font-medium">
              {getInitial(productName)}
            </div>
          </div>
          <div className="space-y-1.5">
            <CardTitle className="text-2xl">Authorize {clientName}</CardTitle>
            <CardDescription>Review what this client gets access to.</CardDescription>
          </div>
        </CardHeader>
        <CardContent className="space-y-6">{children}</CardContent>
      </Card>
    </div>
  )
}

export interface OAuthConsentCardProps extends React.ComponentPropsWithoutRef<'div'> {
  clientName: string
  productName?: string
  redirectUri: string
  email: string
  scopes?: string[]
  error?: string | null
  decision?: OAuthConsentDecision | null
  onApprove?: () => void
  onDeny?: () => void
}

export function OAuthConsentCard({
  clientName,
  productName = 'Your product',
  redirectUri,
  email,
  scopes = [],
  error = null,
  decision = null,
  onApprove,
  onDeny,
  ...props
}: OAuthConsentCardProps) {
  return (
    <ConsentCardShell clientName={clientName} productName={productName} {...props}>
      <dl className="divide-y rounded-lg border text-sm">
        <div className="flex items-center justify-between gap-6 p-4">
          <dt className="text-muted-foreground">Client</dt>
          <dd className="min-w-0 break-all text-right font-medium">{clientName}</dd>
        </div>
        <div className="flex items-center justify-between gap-6 p-4">
          <dt className="text-muted-foreground">Redirects to</dt>
          <dd className="min-w-0 break-all text-right font-medium">{redirectUri}</dd>
        </div>
        <div className="flex items-center justify-between gap-6 p-4">
          <dt className="text-muted-foreground">Signed in as</dt>
          <dd className="min-w-0 break-all text-right font-medium">{email}</dd>
        </div>
        {scopes.length > 0 && (
          <div className="flex items-center justify-between gap-6 p-4">
            <dt className="text-muted-foreground">Scopes</dt>
            <dd className="min-w-0 break-all text-right font-medium">{scopes.join(', ')}</dd>
          </div>
        )}
      </dl>
      <p className="text-sm text-muted-foreground">
        Allow access only if you recognize this application. It can act on your behalf only within
        the requested permissions and the access you already have.
      </p>
      {error && (
        <p role="alert" className="text-sm text-destructive">
          {error}
        </p>
      )}
      <div className="flex flex-col-reverse gap-2 sm:flex-row sm:justify-end">
        <Button type="button" variant="outline" disabled={decision !== null} onClick={onDeny}>
          {decision === 'deny' ? 'Denying...' : 'Deny'}
        </Button>
        <Button type="button" disabled={decision !== null} onClick={onApprove}>
          {decision === 'approve' ? 'Allowing...' : 'Allow access'}
        </Button>
      </div>
    </ConsentCardShell>
  )
}

interface OAuthConsentProps extends React.ComponentPropsWithoutRef<'div'> {
  authorizationId?: string | null
  signInPath?: string
  productName?: string
}

export function OAuthConsent({
  authorizationId,
  signInPath = '/auth/login',
  productName = 'Your product',
  ...props
}: OAuthConsentProps) {
  const { details, email, error, isLoading, decision, approve, deny } = useOAuthConsent({
    authorizationId,
    signInPath,
  })

  if (isLoading || !details || !email) {
    return (
      <ConsentCardShell clientName="OAuth client" productName={productName} {...props}>
        {isLoading ? (
          <p role="status" className="text-sm text-muted-foreground">
            Loading authorization request...
          </p>
        ) : (
          <p role="alert" className="text-sm text-destructive">
            {error ??
              'Unable to load the authorization request. Start again from your OAuth client.'}
          </p>
        )}
      </ConsentCardShell>
    )
  }

  return (
    <OAuthConsentCard
      clientName={details.client.name}
      productName={productName}
      redirectUri={details.redirect_uri}
      email={email}
      scopes={details.scope.split(' ').filter(Boolean)}
      error={error}
      decision={decision}
      onApprove={() => void approve()}
      onDeny={() => void deny()}
      {...props}
    />
  )
}

import { isAuthSessionMissingError } from '@supabase/supabase-js'
import type { OAuthAuthorizationDetails } from '@supabase/supabase-js'
import { useCallback, useEffect, useRef, useState } from 'react'

import { createClient } from '@/registry/default/clients/react/lib/supabase/client'

export type OAuthConsentDecision = 'approve' | 'deny'

export interface UseOAuthConsentOptions {
  authorizationId?: string | null
  signInPath?: string
}

const sameOriginPath = (path: string | null | undefined, fallback = '/') =>
  path?.startsWith('/') && !path.startsWith('//') ? path : fallback

const withNextParam = (path: string, next: string) =>
  `${path}${path.includes('?') ? '&' : '?'}next=${encodeURIComponent(next)}`

const useOAuthConsent = ({
  authorizationId,
  signInPath = '/auth/login',
}: UseOAuthConsentOptions) => {
  const [details, setDetails] = useState<OAuthAuthorizationDetails | null>(null)
  const [error, setError] = useState<string | null>(null)
  const [isLoading, setIsLoading] = useState(true)
  const [decision, setDecision] = useState<OAuthConsentDecision | null>(null)
  const isDeciding = useRef(false)

  useEffect(() => {
    let active = true

    const loadAuthorization = async () => {
      setIsLoading(true)
      setError(null)
      setDetails(null)
      setDecision(null)

      if (!authorizationId) {
        setError('This page needs an authorization_id. Start again from your OAuth client.')
        setIsLoading(false)
        return
      }

      const supabase = createClient()
      const {
        data: { user },
        error: userError,
      } = await supabase.auth.getUser()

      if (userError && !isAuthSessionMissingError(userError)) {
        if (active) {
          setError(userError.message)
          setIsLoading(false)
        }
        return
      }

      if (!user) {
        const next = `${window.location.pathname}${window.location.search}`
        window.location.replace(withNextParam(sameOriginPath(signInPath, '/auth/login'), next))
        return
      }

      const { data, error } = await supabase.auth.oauth.getAuthorizationDetails(authorizationId)
      if (error) {
        if (active) {
          setError(error.message)
          setIsLoading(false)
        }
        return
      }

      if (!('authorization_id' in data)) {
        window.location.replace(data.redirect_url)
        return
      }

      if (active) {
        setDetails(data)
        setIsLoading(false)
      }
    }

    void loadAuthorization()
    return () => {
      active = false
    }
  }, [authorizationId, signInPath])

  const decide = useCallback(
    async (action: OAuthConsentDecision) => {
      if (!authorizationId || isDeciding.current) return

      isDeciding.current = true
      setDecision(action)
      setError(null)
      const supabase = createClient()
      const result =
        action === 'approve'
          ? await supabase.auth.oauth.approveAuthorization(authorizationId, {
              skipBrowserRedirect: true,
            })
          : await supabase.auth.oauth.denyAuthorization(authorizationId, {
              skipBrowserRedirect: true,
            })

      if (result.error) {
        setError(result.error.message)
        setDecision(null)
        isDeciding.current = false
        return
      }

      if (!result.data?.redirect_url) {
        setError('The server did not return a redirect. Start again from your OAuth client.')
        setDecision(null)
        isDeciding.current = false
        return
      }

      window.location.assign(result.data.redirect_url)
    },
    [authorizationId]
  )

  return {
    details,
    email: details?.user.email ?? null,
    error,
    isLoading,
    decision,
    approve: () => decide('approve'),
    deny: () => decide('deny'),
  }
}

type UseOAuthConsentReturn = ReturnType<typeof useOAuthConsent>

export { useOAuthConsent, type OAuthAuthorizationDetails, type UseOAuthConsentReturn }

import { createClient as createSupabaseClient } from '@supabase/supabase-js'

export function createClient() {
  return createSupabaseClient(
    import.meta.env.VITE_SUPABASE_URL!,
    import.meta.env.VITE_SUPABASE_PUBLISHABLE_KEY!
  )
}
